INSERT INTO onboarding_advice (contribution_type, purpose, sentences) VALUES
  ('doc', 'portfolio', $$["문서 기여는 코드 diff보다 리뷰가 빠르게 끝나는 경우가 많아, 짧은 기간 안에 머지된 PR 개수를 포트폴리오에 채우기 좋아요.","README나 가이드 개선 PR은 실제 사용자가 겪는 불편을 직접 지적하고 고친 기록이라, 면접에서 왜 이걸 고쳤는지 설명하기 쉬운 소재가 돼요.","번역 기여는 언어 실력과 오픈소스 이력을 동시에 보여줄 수 있어서, 포트폴리오 한 줄에 두 가지 강점을 같이 담을 수 있어요.","문서 PR이 쌓이다 보면 자연스럽게 그 프로젝트의 구조를 설명할 수 있게 되는데, 이 설명 능력 자체가 다음 단계(버그 수정, 기능 구현) 기여의 발판이 돼요.","채용 담당자는 커밋 수보다 이 사람이 남긴 흔적이 실제로 쓰이는지를 보는 경우가 많아서, 오래 유지되는 문서 기여 하나가 여러 개의 작은 PR보다 설득력 있을 수 있어요."]$$::jsonb),
  ('doc', 'growth', $$["문서를 고치려면 그 기능이 실제로 어떻게 동작하는지 먼저 이해해야 해서, 코드를 안 짜도 코드베이스 이해도가 꽤 올라가요.","리뷰어가 문장 하나하나에 피드백을 주는 경우가 많아, 짧은 글이라도 명확하게 쓰는 법을 배우는 좋은 연습이 돼요.","문서 기여를 반복하다 보면 프로젝트 전체 구조가 눈에 들어오기 시작하는데, 이 시점이 버그 수정으로 넘어가기 좋은 타이밍인 경우가 많아요.","다른 언어로 번역하면서 원문의 애매한 표현을 발견하게 되는 경우가 있는데, 이런 발견 자체가 원저자에게도 도움이 되는 기여예요.","처음부터 큰 기능을 건드리기보다, 문서로 프로젝트에 적응하는 기간을 가지면 이후 코드 기여의 시행착오가 줄어드는 편이에요."]$$::jsonb),
  ('doc', 'community', $$["문서 개선은 언어 장벽 때문에 기여를 망설이던 사람들에게 실질적인 도움이 되는 경우가 많아, 생태계에 바로 체감되는 기여예요.","번역 작업은 다른 지역 커뮤니티와 연결되는 통로가 되기도 해서, 프로젝트 안에서 자연스럽게 네트워크가 넓어져요.","README 하나를 고치는 것도 그 프로젝트의 첫인상을 바꾸는 일이라, 다음 기여자가 더 쉽게 들어올 수 있는 환경을 만드는 셈이에요.","문서 기여자는 유지보수자와 소통할 일이 잦아서, 코드 기여보다 먼저 커뮤니티 안에서 얼굴을 알리기 좋은 경로가 되곤 해요.","오래된 문서를 최신 상태로 정리하는 기여는 눈에 잘 안 띄지만, 그 프로젝트를 계속 쓰는 사람들 입장에서는 꾸준히 도움이 되는 일이에요."]$$::jsonb),
  ('bug', 'portfolio', $$["버그 수정 PR은 무엇을, 왜, 어떻게 고쳤는지가 명확해서, 포트폴리오에 정리할 때 스토리를 만들기 쉬운 편이에요.","작은 버그부터 시작해 여러 저장소에 걸쳐 기여하면, 한 프로젝트 안에서만 활동한 것보다 폭넓은 코드베이스 적응력을 보여줄 수 있어요.","재현 조건을 찾고 원인을 좁혀가는 과정 자체가 문제 해결 능력을 보여주는 좋은 사례가 되는 경우가 많아요.","머지된 버그 수정 PR 링크는 실제로 동작하는 코드를 남겼다는 증거라, 이력서의 다른 항목보다 검증하기 쉬운 소재예요.","작은 이슈라도 꾸준히 해결한 기록이 쌓이면, 하나의 큰 프로젝트 경험보다 꾸준함을 보여주는 데는 더 유리할 수 있어요."]$$::jsonb),
  ('bug', 'growth', $$["버그를 고치려면 다른 사람이 짠 코드를 읽고 흐름을 따라가야 해서, 이 과정 자체가 코드 리딩 실력을 키우는 데 도움이 돼요.","재현부터 원인 파악까지 직접 해보는 경험은, 강의나 문서로 배우기 어려운 디버깅 감각을 길러주는 경우가 많아요.","작은 버그 수정을 반복하다 보면 그 프로젝트의 설계 의도가 조금씩 눈에 들어오는데, 이게 다음 단계(기능 구현) 기여로 넘어가는 발판이 돼요.","리뷰어가 왜 이렇게 고쳤는지 되묻는 경우가 많아서, 원인과 해결책을 논리적으로 설명하는 연습이 자연스럽게 쌓여요.","처음엔 사소해 보이는 수정이라도, 엣지 케이스를 고려하는 습관은 실무에서도 그대로 쓰이는 감각이에요."]$$::jsonb),
  ('bug', 'community', $$["버그 리포트에 바로 반응해서 고치는 기여자는 유지보수자 입장에서 특히 반가운 존재라, 신뢰를 빠르게 쌓을 수 있는 경로예요.","오래 방치된 이슈를 해결하면 그 이슈를 기다리던 다른 사용자들에게도 바로 체감되는 도움이 돼요.","버그 수정으로 시작한 인연이 이후 그 프로젝트의 리뷰어나 메인테이너로 이어지는 경우도 업계에서는 흔한 편이에요.","이슈 트래커에서 다른 기여자들과 원인을 같이 좁혀가는 과정 자체가 커뮤니티 참여의 좋은 시작점이 될 수 있어요.","작은 저장소일수록 버그 수정 하나의 영향이 상대적으로 크게 느껴져서, 커뮤니티 안에서 존재감을 만들기에 좋은 편이에요."]$$::jsonb),
  ('feat', 'portfolio', $$["기능 구현 PR은 설계 논의부터 구현까지 과정이 남아 있어서, 포트폴리오에 어떻게 접근했는지를 설명할 자료가 풍부해요.","새 기능을 붙이려면 기존 코드와의 충돌을 고려해야 해서, 이 과정에서 얻는 설계 감각이 이력서에도 잘 드러나는 경험이 돼요.","리뷰 과정에서 나온 논의 스레드 자체가, 면접에서 협업하며 코드를 개선한 경험을 보여줄 좋은 자료가 되는 경우가 많아요.","작은 기능 하나라도 처음부터 끝까지 책임지고 구현한 경험은, 여러 개의 작은 수정보다 임팩트 있게 보이는 편이에요.","기능 구현은 리뷰 사이클이 긴 경우가 많으니, 포트폴리오에 담을 때는 머지 완료 여부보다 과정 자체를 강조하는 것도 방법이에요."]$$::jsonb),
  ('feat', 'growth', $$["새 기능을 설계하려면 기존 아키텍처를 먼저 이해해야 해서, 이 과정에서 얻는 배움이 버그 수정보다 큰 경우가 많아요.","메인테이너와 설계 방향을 논의하는 경험은, 혼자 공부해서는 얻기 어려운 실전 감각을 길러줘요.","처음엔 작은 옵션 추가 같은 기능부터 시작하면, 큰 기능으로 넘어가기 전 프로젝트 컨벤션에 적응하는 데 도움이 돼요.","기능 구현 중 리뷰에서 받는 피드백은 대개 설계 관점의 지적이라, 코드 스타일 교정보다 더 오래 남는 배움이 되는 편이에요.","구현한 기능이 실제로 쓰이는 걸 보는 경험은, 성장 동기를 오래 유지하는 데 특히 도움이 되는 편이에요."]$$::jsonb),
  ('feat', 'community', $$["새 기능은 그 프로젝트의 방향성과 맞닿아 있어서, 제안 단계부터 참여하면 커뮤니티 논의에 자연스럽게 들어가게 돼요.","사용자들이 요청해온 기능을 구현하면, 그 요청을 남긴 사람들과 바로 연결되는 계기가 되는 경우가 많아요.","기능 구현자는 이후 그 기능의 유지보수까지 자연스럽게 이어지는 경우가 있어서, 프로젝트 안에서 역할이 커지기 쉬운 편이에요.","RFC나 이슈 논의에 의견을 남기는 것부터 시작해도, 그 자체로 커뮤니티에 이름을 알리는 좋은 출발점이 돼요.","작은 프로젝트일수록 기능 하나를 구현한 기여자가 핵심 인력으로 자리잡는 경우가 상대적으로 흔한 편이에요."]$$::jsonb),
  ('test', 'portfolio', $$["테스트 코드는 그 자체로 이 프로젝트를 얼마나 이해했는지를 보여주는 지표라, 포트폴리오에서 신뢰도를 높이는 소재가 돼요.","커버리지가 낮은 영역을 찾아 테스트를 추가한 기록은, 문제를 스스로 찾아 해결했다는 근거로 쓰기 좋은 편이에요.","테스트 작성 PR은 리뷰가 비교적 명확한 기준(통과/실패)으로 진행돼서, 머지까지 걸리는 시간이 상대적으로 짧은 경우가 많아요.","엣지 케이스를 찾아내는 테스트는 꼼꼼함을 보여주는 근거가 되는데, 이런 성향은 실무 면접에서도 자주 확인하는 부분이에요.","테스트 기여가 쌓이면 그 프로젝트의 동작 방식을 폭넓게 알게 돼서, 이후 버그 수정이나 기능 구현으로 넘어가기도 수월해져요."]$$::jsonb),
  ('test', 'growth', $$["테스트를 짜려면 코드가 실패하는 모든 경우를 상상해봐야 해서, 이 훈련 자체가 꼼꼼한 개발 습관을 만드는 데 도움이 돼요.","기존 테스트 코드를 읽는 것만으로도 그 프로젝트가 무엇을 중요한 동작으로 보는지 파악하는 좋은 방법이 돼요.","테스트가 실패하는 이유를 추적하다 보면 자연스럽게 디버깅 능력이 함께 늘어나는 경우가 많아요.","작은 유닛 테스트부터 시작해서 통합 테스트로 넘어가면, 테스트 설계에 대한 감각을 단계적으로 쌓을 수 있어요.","테스트 작성은 코드를 고치는 게 아니라 검증하는 관점을 길러줘서, 이후 어떤 기여를 하든 품질을 보는 눈이 달라지는 편이에요."]$$::jsonb),
  ('test', 'community', $$["테스트가 부족한 프로젝트에 커버리지를 보태는 기여는, 유지보수자 입장에서 특히 반가워하는 종류의 도움이에요.","안정성이 높아진 프로젝트는 더 많은 사람이 안심하고 쓰게 되니, 눈에 잘 안 띄어도 생태계 전체에 도움이 되는 기여예요.","CI가 자주 깨지는 프로젝트에 테스트를 보강하면, 다른 기여자들의 작업 속도까지 함께 빨라지는 효과가 있어요.","테스트 기여는 코드 스타일 논쟁이 적어서, 처음 커뮤니티에 들어갈 때 상대적으로 마찰 없이 시작하기 좋은 편이에요.","테스트를 계기로 메인테이너와 소통하다 보면, 자연스럽게 그 프로젝트의 신뢰받는 기여자로 자리잡는 경우가 많아요."]$$::jsonb),
  ('review', 'portfolio', $$["코드 리뷰 기록은 다른 사람의 코드를 읽고 판단하는 능력을 보여주는 자료라, 시니어 포지션 지원 시 특히 설득력 있는 소재가 돼요.","리뷰 코멘트가 쌓이면 그 자체로 특정 언어나 프레임워크에 대한 이해도를 드러내는 기록이 돼요.","PR 작성보다 리뷰는 시간 대비 남길 수 있는 흔적이 많아서, 바쁜 와중에도 꾸준한 기여 이력을 만들기 좋은 편이에요.","좋은 리뷰 코멘트 하나는 작성자에게도, 지켜보는 사람에게도 기억에 남기 때문에, 이력서 밖에서도 평판이 쌓이는 경우가 많아요.","리뷰 경험은 협업 능력을 직접 보여주는 항목이라, 코드만으로는 채우기 어려운 포트폴리오의 빈 부분을 메우기 좋아요."]$$::jsonb),
  ('review', 'growth', $$["다른 사람의 PR을 리뷰하려면 그 코드가 왜 이렇게 짜였는지 먼저 이해해야 해서, 읽기 능력이 빠르게 느는 경우가 많아요.","리뷰를 하다 보면 이 방식이 더 나은 이유를 언어화하게 되는데, 이 과정이 자기 코드를 쓸 때도 그대로 도움이 돼요.","처음엔 사소한 오타나 스타일 코멘트부터 시작해도 괜찮고, 점점 설계 관점의 코멘트로 넓혀가는 게 자연스러운 순서예요.","여러 사람의 PR을 보다 보면 같은 문제를 푸는 다양한 방식을 접하게 돼서, 혼자 코드를 쓸 때보다 시야가 넓어지는 편이에요.","리뷰는 실수를 미리 잡아내는 훈련이라, 이후 자신의 코드를 검토할 때도 놓치는 부분이 줄어드는 경우가 많아요."]$$::jsonb),
  ('review', 'community', $$["리뷰는 프로젝트에 코드를 직접 추가하지 않으면서도 가장 활발하게 참여할 수 있는 방법 중 하나예요.","신규 기여자의 PR에 친절한 피드백을 남기면, 그 사람이 계속 남을지 여부에 실제로 영향을 주는 경우가 많아요.","리뷰를 꾸준히 하다 보면 메인테이너들 눈에 먼저 띄어서, 커밋 권한이나 협업 제안으로 이어지는 경우도 있어요.","리뷰어가 부족한 프로젝트일수록 리뷰 하나하나의 체감 가치가 커서, 작은 참여로도 큰 도움이 되는 편이에요.","코멘트를 남기는 것도 기여라는 인식이 있는 커뮤니티가 많아서, 코드를 짜지 않아도 존재감을 쌓을 수 있는 경로예요."]$$::jsonb);
